"""RefKey and REFERENCES_META must match shared/references/references.json (generated by make references-generate)."""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from references import REFERENCES_META, RefKey

SOURCE = Path("/app/shared/references/references.json")


@pytest.fixture(scope="module")
def references() -> list[dict]:
    if not SOURCE.is_file():
        pytest.skip(f"{SOURCE} not mounted")
    return json.loads(SOURCE.read_text(encoding="utf-8"))["references"]


def test_keys_in_order(references):
    assert [r["key"] for r in references] == [k.value for k in RefKey]


def test_meta_matches(references):
    for ref in references:
        meta = REFERENCES_META[RefKey(ref["key"])]
        assert (meta["index"], meta["name"], meta["year"], meta.get("url")) == (
            ref["index"], ref["name"], ref["year"], ref.get("url")
        ), f"{ref['key']}: run make references-generate"
